const input = $input.first().json;
const body = input.body || input;

return [{ json: {
  session_id: body.session_id || 'sess_' + Date.now(),
  visitor_id: body.visitor_id,
  email: body.email || null,
  name: body.name || null,
  message: body.message || '',
  page_url: body.page_url || '',
  client_id: body.client_id,
  metadata: body.metadata || {}
}}];

const response = $input.first().json;
const chatData = $node['Parse Chat'].json;
const aiReply = response.choices?.[0]?.message?.content || 'Maaf, saya tidak bisa memproses pesan Anda saat ini. Tim kami akan segera membantu.';

const needsHandoff = aiReply.startsWith('[HANDOFF]');
const cleanReply = aiReply.replace('[HANDOFF]', '').trim();

// Detect if visitor provided email in message
const emailMatch = chatData.message.match(/[\w.-]+@[\w.-]+\.[a-zA-Z]{2,}/);
const detectedEmail = emailMatch ? emailMatch[0] : chatData.email;

// Detect intent
const msg = chatData.message.toLowerCase();
let intent = 'general';
if (msg.includes('harga') || msg.includes('price') || msg.includes('biaya')) intent = 'pricing';
else if (msg.includes('demo') || msg.includes('coba') || msg.includes('trial')) intent = 'demo';
else if (msg.includes('fitur') || msg.includes('feature')) intent = 'features';
else if (msg.includes('bantuan') || msg.includes('help') || msg.includes('masalah')) intent = 'support';

return [{ json: {
  ...chatData,
  ai_reply: cleanReply,
  needs_handoff: needsHandoff,
  detected_email: detectedEmail,
  intent: intent,
  should_create_lead: !!detectedEmail && (intent === 'pricing' || intent === 'demo')
}}];

